 @Test void saved_menu_and_dictionary_reads_reach_visible_server_text_even_without_new_client_renderers(){
  registry.configureExtensions(true,()->true);
  registry.registerRead("read_saved_menus",(u,c,s)->{ReadResult r=new ReadResult();r.setName(c.getName());r.setCallId(c.getCallId());r.getItems().add(AssistantV4ContextService.map("id",3L,"name","工作日晚餐","people",4,"dishIds",Arrays.asList(7L,8L)));return r;});
  registry.registerRead("get_recommendation_options",(u,c,s)->{ReadResult r=new ReadResult();r.setName(c.getName());r.setCallId(c.getCallId());r.getItems().add(AssistantV4ContextService.map("group","flavor","code","LIGHT","label","清淡"));return r;});
  when(model.step(any())).thenAnswer(i->{StepInput in=i.getArgument(0);if(store.turnRecord(1L,id).getProviderCallsUsed()>1)return finalOutput();StepOutput out=tools(in,"menus","options");out.getReadCalls().get(0).setName("read_saved_menus");out.getReadCalls().get(1).setName("get_recommendation_options");List<?> protocol=(List<?>)out.getProviderContinuation().getAssistantMessage().get("tool_calls");for(int n=0;n<2;n++){Map<?,?> t=(Map<?,?>)protocol.get(n);((Map<String,Object>)t.get("function")).put("name",out.getReadCalls().get(n).getName());}return out;});
  runner.runTurn(1L,id);TurnView view=store.findTurn(1L,id);assertEquals("completed",view.getStatus());assertEquals(2,view.getCards().size());
  String visible=view.getCards().stream().map(Card::getText).filter(Objects::nonNull).collect(java.util.stream.Collectors.joining("\n"));
  assertTrue(visible.contains("工作日晚餐"));assertTrue(visible.contains("4人"));assertTrue(visible.contains("2道菜"));assertTrue(visible.contains("清淡"));assertFalse(visible.contains("LIGHT"));assertFalse(view.getReply().contains("保存"));assertNull(view.getPendingAction());
 }
