 @Test void negotiatedNavigationRemainsAnUnconfirmedHandoffWithoutReceipt(){
  TurnRequest request=fixture.request();request.setUiFeatures(Collections.singletonList("handoff_v1"));request.setMessage("以后避开香菜");
  id=store.claimTurn(1L,store.turnRecord(1L,id).getSessionId(),request).getTurnId();registry.configureExtensions(true,()->true);registry.registerUiFeature("handoff_v1");
  AssistantGuidanceService guidance=mock(AssistantGuidanceService.class);runner.setGuidance(guidance);Card card=new Card();card.setId("handoff");card.setType("handoff");card.setTitle("去编辑长期偏好");when(guidance.resolveNavigation(eq(1L),anyMap(),any(),eq("以后避开香菜"))).thenReturn(card);
  StepOutput out=new StepOutput();out.setType("navigation");out.setNavigationIntent(AssistantV4ContextService.map("kind","edit_preferences","ref",Collections.emptyMap()));when(model.step(any())).thenReturn(out);
  runner.runTurn(1L,id);TurnView view=store.findTurn(1L,id);assertEquals("needs_input",view.getStatus());assertEquals("handoff",view.getCards().get(0).getType());assertNull(view.getCards().get(0).getReceiptRef());assertNull(view.getPendingAction());verify(fixture.workspaces,never()).mutate(anyLong(),anyString(),anyString(),any());
 }
 StepOutput tools(StepInput input,String... ids){StepOutput out=new StepOutput();out.setType("read_calls");ProviderContinuation p=new ProviderContinuation();if(input.getProviderContinuation()!=null){p.getMessages().addAll(input.getProviderContinuation().getMessages());for(ReadResult result:input.getReadResults()){Map<String,Object> tool=new LinkedHashMap<>();tool.put("role","tool");tool.put("tool_call_id",result.getCallId());try{tool.put("content",json.writeValueAsString(result));}catch(Exception e){throw new RuntimeException(e);}p.getMessages().add(tool);}}Map<String,Object> message=new LinkedHashMap<>();message.put("role","assistant");message.put("reasoning_content","private-reasoning");List<Map<String,Object>> protocol=new ArrayList<>();for(String id:ids){ToolRead call=new ToolRead();call.setCallId(id);call.setName("search_dishes");out.getReadCalls().add(call);Map<String,Object> tool=new LinkedHashMap<>(),function=new LinkedHashMap<>();function.put("name",call.getName());function.put("arguments","{}");tool.put("id",id);tool.put("type","function");tool.put("function",function);protocol.add(tool);}message.put("tool_calls",protocol);p.setAssistantMessage(message);p.getMessages().add(message);out.setProviderContinuation(p);return out;}
 StepOutput action(String kind,Map<String,Object> arguments){StepOutput out=finalOutput();ActionProposal p=new ActionProposal();ActionIntent a=new ActionIntent();a.setKind(kind);a.setArguments(arguments);p.getSteps().add(a);out.setActionProposal(p);return out;}
 Map<String,Object> draft(long id){Map<String,Object> args=new LinkedHashMap<>();args.put("operation","generate");args.put("selectedDishIds",Collections.singletonList(id));return args;}
