 @Test void draft_then_calendar_then_shopping_uses_receipts_and_no_new_model(){
  registry.registerDraft("draft_update",(u,s,scope)->{TurnResult result=new TurnResult();result.setStatus("completed");Card card=new Card();card.setType("menu");card.setReceiptRef("draft-receipt");result.getCards().add(card);WorkspaceRef ref=new WorkspaceRef();ref.setWorkspaceId("w");ref.setWorkspaceRevision(1L);ref.setPlanVersion(1L);result.setWorkspaceRef(ref);return result;});
  registry.registerPreview("calendar_save",(u,s,scope)->{assertEquals(1L,scope.getExpectedWorkspaceRevision());return preview(s);});registry.registerPreview("shopping_preview",(u,s,scope)->preview(s));
  StepOutput output=action("draft_update",draft(1));ActionIntent calendar=new ActionIntent();calendar.setKind("calendar_save");calendar.getArguments().put("targetDate","2026-10-12");calendar.getArguments().put("targetMealType","dinner");output.getActionProposal().getSteps().add(calendar);ActionIntent shopping=new ActionIntent();shopping.setKind("shopping_preview");Map<String,Object> source=new LinkedHashMap<>();source.put("kind","draft");source.put("workspaceId","w");shopping.getArguments().put("sourceRef",source);output.getActionProposal().getSteps().add(shopping);when(model.step(any())).thenReturn(output);
  runner.runTurn(1L,id);TurnView first=store.findTurn(1L,id);assertEquals("awaiting_confirmation",first.getStatus());assertEquals(1,first.getContinuation().getCursor());assertEquals("step-2",first.getPendingAction().getStepId());Card receipt=new Card();receipt.setReceiptRef("calendar-receipt");store.completeWorkflowStep(1L,id,"step-2","calendar-receipt",receipt);TurnView last=runner.resumeWorkflow(1L,id);assertEquals(2,last.getContinuation().getCursor());assertEquals("step-3",last.getPendingAction().getStepId());assertEquals("calendar-receipt",last.getContinuation().getSteps().get(1).getReceiptRef());verify(model,times(1)).step(any());
 }
